  2	import { FastifyRequest, FastifyReply } from 'fastify';
  3	import { z } from 'zod';
  4	import { ILeaveRequestService } from './leave-request.service';
  5	import { LeaveStatus } from 'shared/types';
  6	
  7	const createSchema = z.object({
  8	  employeeId: z.string().min(1),
  9	  leavePolicyId: z.string().min(1),
 10	  startDate: z.string().refine((val) => !isNaN(Date.parse(val)), {
 11	    message: 'startDate must be a valid date string',
 12	  }),
 13	  endDate: z.string().refine((val) => !isNaN(Date.parse(val)), {
 14	    message: 'endDate must be a valid date string',
 15	  }),
 16	  reason: z.string().optional(),
 17	});
 18	
 19	const updateSchema = z.object({
 20	  startDate: z
 21	    .string()
 22	    .refine((val) => !isNaN(Date.parse(val)), {
 23	      message: 'startDate must be a valid date string',
 24	    })
 25	    .optional(),
 26	  endDate: z
 27	    .string()
 28	    .refine((val) => !isNaN(Date.parse(val)), {
 29	      message: 'endDate must be a valid date string',
 30	    })
 31	    .optional(),
 32	  reason: z.string().optional(),
 33	});
 34	
 35	const idParamsSchema = z.object({
 36	  id: z.string().min(1),
 37	});
 38	
 39	const approveRejectBodySchema = z.object({
 40	  approverId: z.string().min(1),
 41	});
 42	
 43	const cancelBodySchema = z.object({
 44	  cancelledBy: z.string().min(1),
 45	});
 46	
 47	const querySchema = z.object({
 48	  employeeId: z.string().optional(),
 49	  status: z.nativeEnum(LeaveStatus).optional(),
 50	  leavePolicyId: z.string().optional(),
 51	  startDate: z
 52	    .string()
 53	    .refine((val) => !isNaN(Date.parse(val)), {
 54	      message: 'startDate must be a valid date string',
 55	    })
 56	    .optional(),
 57	  endDate: z
 58	    .string()
 59	    .refine((val) => !isNaN(Date.parse(val)), {
 60	      message: 'endDate must be a valid date string',
 61	    })
 62	    .optional(),
 63	});
