 65	export class LeaveRequestController {
 66	  constructor(private readonly leaveRequestService: ILeaveRequestService) {}
 67	
 68	  createLeaveRequest = async (
 69	    request: FastifyRequest,
 70	    reply: FastifyReply,
 71	  ): Promise<void> => {
 72	    const parsed = createSchema.safeParse(request.body);
 73	    if (!parsed.success) {
 74	      return reply.status(400).send({
 75	        error: 'Validation Error',
 76	        details: parsed.error.issues,
 77	      });
 78	    }
 79	
 80	    const dto = {
 81	      employeeId: parsed.data.employeeId,
 82	      leavePolicyId: parsed.data.leavePolicyId,
 83	      startDate: new Date(parsed.data.startDate),
 84	      endDate: new Date(parsed.data.endDate),
 85	      reason: parsed.data.reason,
 86	    };
 87	
 88	    const result = await this.leaveRequestService.create(dto);
 89	    return reply.status(201).send(result);
 90	  };
 91	
 92	  submitLeaveRequest = async (
 93	    request: FastifyRequest,
 94	    reply: FastifyReply,
 95	  ): Promise<void> => {
 96	    const paramsParsed = idParamsSchema.safeParse(request.params);
 97	    if (!paramsParsed.success) {
 98	      return reply.status(400).send({
 99	        error: 'Validation Error',
100	        details: paramsParsed.error.issues,
101	      });
102	    }
103	
104	    const result = await this.leaveRequestService.submit(paramsParsed.data.id);
105	    return reply.status(200).send(result);
106	  };
107	
108	  approveLeaveRequest = async (
109	    request: FastifyRequest,
110	    reply: FastifyReply,
111	  ): Promise<void> => {
112	    const paramsParsed = idParamsSchema.safeParse(request.params);
113	    if (!paramsParsed.success) {
114	      return reply.status(400).send({
115	        error: 'Validation Error',
116	        details: paramsParsed.error.issues,
117	      });
118	    }
119	
120	    const bodyParsed = approveRejectBodySchema.safeParse(request.body);
121	    if (!bodyParsed.success) {
122	      return reply.status(400).send({
123	        error: 'Validation Error',
124	        details: bodyParsed.error.issues,
125	      });
126	    }
127	
128	    const result = await this.leaveRequestService.approve(
129	      paramsParsed.data.id,
130	      bodyParsed.data.approverId,
131	    );
132	    return reply.status(200).send(result);
133	  };
134	
135	  rejectLeaveRequest = async (
136	    request: FastifyRequest,
137	    reply: FastifyReply,
138	  ): Promise<void> => {
139	    const paramsParsed = idParamsSchema.safeParse(request.params);
140	    if (!paramsParsed.success) {
141	      return reply.status(400).send({
142	        error: 'Validation Error',
143	        details: paramsParsed.error.issues,
144	      });
145	    }
146	
147	    const bodyParsed = approveRejectBodySchema.safeParse(request.body);
148	    if (!bodyParsed.success) {
149	      return reply.status(400).send({
150	        error: 'Validation Error',
151	        details: bodyParsed.error.issues,
152	      });
153	    }
154	
155	    const result = await this.leaveRequestService.reject(
156	      paramsParsed.data.id,
157	      bodyParsed.data.approverId,
158	    );
159	    return reply.status(200).send(result);
160	  };
161	
162	  cancelLeaveRequest = async (
163	    request: FastifyRequest,
164	    reply: FastifyReply,
165	  ): Promise<void> => {
166	    const paramsParsed = idParamsSchema.safeParse(request.params);
167	    if (!paramsParsed.success) {
168	      return reply.status(400).send({
169	        error: 'Validation Error',
170	        details: paramsParsed.error.issues,
171	      });
172	    }
173	
174	    const bodyParsed = cancelBodySchema.safeParse(request.body);
175	    if (!bodyParsed.success) {
176	      return reply.status(400).send({
177	        error: 'Validation Error',
178	        details: bodyParsed.error.issues,
179	      });
180	    }
181	
182	    const result = await this.leaveRequestService.cancel(
183	      paramsParsed.data.id,
184	      bodyParsed.data.cancelledBy,
185	    );
186	    return reply.status(200).send(result);
187	  };
188	
189	  updateLeaveRequest = async (
190	    request: FastifyRequest,
191	    reply: FastifyReply,
192	  ): Promise<void> => {
193	    const paramsParsed = idParamsSchema.safeParse(request.params);
194	    if (!paramsParsed.success) {
195	      return reply.status(400).send({
196	        error: 'Validation Error',
197	        details: paramsParsed.error.issues,
198	      });
199	    }
200	
201	    const bodyParsed = updateSchema.safeParse(request.body);
202	    if (!bodyParsed.success) {
203	      return reply.status(400).send({
204	        error: 'Validation Error',
205	        details: bodyParsed.error.issues,
206	      });
207	    }
208	
209	    const dto: {
210	      startDate?: Date;
211	      endDate?: Date;
212	      reason?: string;
213	    } = {};
214	
215	    if (bodyParsed.data.startDate) {
216	      dto.startDate = new Date(bodyParsed.data.startDate);
217	    }
218	    if (bodyParsed.data.endDate) {
219	      dto.endDate = new Date(bodyParsed.data.endDate);
220	    }
221	    if (bodyParsed.data.reason !== undefined) {
222	      dto.reason = bodyParsed.data.reason;
223	    }
224	
225	    const result = await this.leaveRequestService.update(paramsParsed.data.id, dto);
226	    return reply.status(200).send(result);
227	  };
228	
229	  getLeaveRequest = async (
230	    request: FastifyRequest,
231	    reply: FastifyReply,
232	  ): Promise<void> => {
233	    const paramsParsed = idParamsSchema.safeParse(request.params);
234	    if (!paramsParsed.success) {
235	      return reply.status(400).send({
236	        error: 'Validation Error',
237	        details: paramsParsed.error.issues,
238	      });
239	    }
240	
241	    const result = await this.leaveRequestService.getById(paramsParsed.data.id);
242	    return reply.status(200).send(result);
243	  };
244	
245	  queryLeaveRequests = async (
246	    request: FastifyRequest,
247	    reply: FastifyReply,
248	  ): Promise<void> => {
249	    const queryParsed = querySchema.safeParse(request.query);
250	    if (!queryParsed.success) {
251	      return reply.status(400).send({
252	        error: 'Validation Error',
253	        details: queryParsed.error.issues,
254	      });
255	    }
256	
257	    const params: {
258	      employeeId?: string;
259	      status?: LeaveStatus;
260	      leavePolicyId?: string;
261	      startDate?: Date;
262	      endDate?: Date;
263	    } = {};
264	
265	    if (queryParsed.data.employeeId) {
266	      params.employeeId = queryParsed.data.employeeId;
267	    }
268	    if (queryParsed.data.status) {
269	      params.status = queryParsed.data.status;
270	    }
271	    if (queryParsed.data.leavePolicyId) {
272	      params.leavePolicyId = queryParsed.data.leavePolicyId;
273	    }
274	    if (queryParsed.data.startDate) {
275	      params.startDate = new Date(queryParsed.data.startDate);
276	    }
277	    if (queryParsed.data.endDate) {
278	      params.endDate = new Date(queryParsed.data.endDate);
279	    }
280	
281	    const result = await this.leaveRequestService.query(params);
282	    return reply.status(200).send(result);
283	  };
284	}
